import { ReactNode } from 'react';

import { IndicatorsDisplay } from '../../core/components/annotations-atoms/types/indicator.js';
import { WithId } from '../../core/types/with-id.js';
import { SameValueGroup } from '../components/annotations/util/group-markers.js';

export interface HistogramRangeAnnotation {
  /** From number of annotation. */
  from: number;
  /** To number of annotation. */
  to: number;
}

export type HistogramAnnotation = HistogramRangeAnnotation | number;

export function isHistogramValueAnnotation(
  annotation: HistogramAnnotation,
): annotation is number {
  return typeof annotation === 'number';
}

export type HistogramAnnotationsTrackRendererProps =
  HistogramAnnotationsTrackProps & {
    markers: WithId<HistogramAnnotationsMarkerProps>[];
    annotationsActions?: (annotation: HistogramAnnotationMarker) => ReactNode;
  };

export type HistogramAnnotationsConfigProps = {
  tracks: HistogramAnnotationsTrackRendererProps[];
} & HistogramAnnotationsProps;

export interface HistogramAnnotationsMarkerProps {
  /** Value of the annotation marker */
  value: HistogramAnnotation;
  /** Title of the annotation. */
  title: string;
  /** Details about the marker. */
  description?: string;
  /** Color of the marker*/
  color?: string;
  /** Defines the display behaviour of marker's indicators of a particular track
   * auto - a default behavior. Indicators are only shown on markers hover
   * always - always show the marker indicator
   * never - never shown the marker indicator
   */
  indicatorsDisplay?: IndicatorsDisplay;
  /** Annotation marker character (letter/emoji/icon/glyph or Unicode character). */
  symbol?: string | ReactNode;
  /** Flag to hide a marker */
  hidden?: boolean;
  /** Priority for annotation marker */
  priority?: number;
}

export type HistogramAnnotationMarker = HistogramAnnotationsMarkerProps;

export interface HistogramAnnotationsTrackProps {
  /** Color of the track. */
  color?: string;
  /** Optional label for the track. */
  label?: string;
  /** Whether this track should be visible */
  hidden?: boolean;
  /** Defines how to show the annotations indicators: always, never, or on hover (auto) at Track level */
  indicatorsDisplay?: IndicatorsDisplay;
  /** Annotations markers character (letter/emoji/icon/glyph or Unicode character). */
  symbol?: ReactNode;
  /** Priority for annotation track */
  priority?: number;
}

export interface HistogramAnnotationsProps {
  /** How many tracks to show by default, if there are more tracks than the specified here a scrollbar will be added. */
  visibleTracksLimit?: number;
  /**
   * Optional flag to determine whether to display labels.
   * @defaultValue false
   */
  showLabels?: boolean;
  annotationsActions?: (annotation: HistogramAnnotationMarker) => ReactNode;
}

export interface HistogramAnnotationsDataProps {
  tracks: (Omit<HistogramAnnotationsTrackRendererProps, 'markers'> & {
    tooltipMarkers: WithId<HistogramAnnotationsMarkerProps>[][][];
    prioritizedMarkers: SameValueGroup[][];
  })[];
}
